package com.siiiweb.gateway;import com.siiiweb.common.JwtUtil;import org.springframework.cloud.gateway.filter.GlobalFilter;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.core.Ordered;import org.springframework.http.HttpStatus;import reactor.core.publisher.Mono;
@Configuration public class JwtGatewayFilter{ @Bean GlobalFilter auth(){return (exchange,chain)->{String p=exchange.getRequest().getPath().value(); if(!p.contains("/api/admin/")||p.endsWith("/login")||p.endsWith("/refresh"))return chain.filter(exchange); String h=exchange.getRequest().getHeaders().getFirst("Authorization"); try{if(h==null||!h.startsWith("Bearer "))throw new RuntimeException(); JwtUtil.parse(h.substring(7)); return chain.filter(exchange);}catch(Exception e){exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);return exchange.getResponse().setComplete();}};} }
